SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dc1b74e793e7a84b95e7f13cfd591806b7129dca/content/books/zizhi-tongjian/vol-288/year-0948/part-04/sources/library/jiuwudaishi-085-jin-captive-audience-948/source.txt", "note": "《旧五代史》卷八十五，段落 jiu-wudaishi-205deb4a7860-p002054；EPUB电子本，纸本及异文待核", "id": "75bf0ec8-4efd-5b92-890d-7b32f3e290ce"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dc1b74e793e7a84b95e7f13cfd591806b7129dca/content/books/zizhi-tongjian/vol-288/year-0948/part-04/sources/library/jiuwudaishi-101-june-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002456；EPUB电子本，纸本及异文待核", "id": "e338613d-acce-5152-b8b3-8ee376b93de7"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dc1b74e793e7a84b95e7f13cfd591806b7129dca/content/books/zizhi-tongjian/vol-288/year-0948/part-04/sources/library/jiuwudaishi-101-may-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002455；EPUB电子本，纸本及异文待核", "id": "c8870424-9c8e-5b43-8dd7-fd56700a8091"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dc1b74e793e7a84b95e7f13cfd591806b7129dca/content/books/zizhi-tongjian/vol-288/year-0948/part-04/sources/library/tongjian-288-948-april-august/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003417；电子底本待考，分段待核", "id": "91af4274-f01f-53f1-9027-d3c8fdd8674f"}, {"title": "新五代史·卷十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dc1b74e793e