INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "尚洪迁", "aliases": ["尚洪遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将领。948年《资治通鉴》记其任宁江节度使、侍卫步军都指挥使，四月乙未被任为西面行营都虞候；《旧五代史》写西南面行营。生卒年尚未录入。", "biography": null, "status": "draft", "id": "014bf6c4-c82b-5b88-9792-2530cf2dd254"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "冯氏（石重贵后）", "aliases": ["吴国夫人冯氏", "馮氏（石重贵后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯濛的女儿、冯玉的妹妹。先嫁石重胤，夫死后守寡；石敬瑭去世后被石重贵纳入宫中，943年十月戊申由吴国夫人立为皇后，随后参与政务。具体个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "a9036cf2-4b6b-5883-a952-511979eb35f7"}, {"name": "禅奴利", "aliases": ["禅奴", "禪奴", "禅奴舍利"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹皇帝耶律阮的妻兄，《通鉴》后文简称禅奴，《旧五代史》写禅奴舍利。948年向被俘的石重贵求其未婚幼女，遭拒后，耶律阮强行取女赐给他。各书行程月份及旧史末句受赐者译名差异分别保留，生卒年未载。", "biography": null, "status": "draft", "id": "0ee840e1-bd2f-58be-be4e-1eca17f2f7e1"}, {"name": "石重贵之女（948年被赐给禅奴者）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石重贵未具姓名的幼女，948年尚未出嫁。禅奴利求娶时，石重贵以年幼拒绝；后来耶律阮派人强行带走，将她赐给禅奴利。具体出生年、母亲及婚礼是否举行均未载，以本次经历限定身份，不合并其他未具名女儿。", "biography": null, "status": "draft", "id": "2cc2deb8-acbc-56e8-a593-2d5f609ab2ce"}, {"name": "徐彦（后蜀凤州刺史）", "aliases": ["徐彦（凤州刺史）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "948年任后蜀凤州刺史。王景崇致书请求互市，孟昶命徐彦回信招引王景崇。与闽国同名巫者徐彦分开，未作无证合并。生卒年未载。", "biography": null, "status": "draft", "id": "c0ad81d4-c636-5046-90c8-baf17b94d984"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "徐台符", "aliases": ["徐臺符"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武强人，后晋金部郎中、知制诰。944年六月戊辰任翰林学士。生卒年本段未载。", "biography": null, "status": "draft", "id": "28c5a951-7fb9-591a-b527-988ede5145c7"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
